(6892366, 1038973, 135629, '<td valign="top">Utterly quiet.</td>', 'Utterly quiet.', '2012-10-27 13:31:20.000000', NULL, 1),
(6892367, 1038838, 135629, '<td valign="top">To me this conveys censorship of music, which is a form of silence. I could see it used in an add :) I appreciate the outside the box approach with your image and I think it get''s the point across nicely. This is my second time through the images, and I am bumping this up a couple because I am reading more into it. On the photography side, great work I understand the cord being cropped out at the bottim with your angle because it would have been a mess of cord, and due to the angle of the shot and the limited size of the entries here... you are left with a bit of black space at the top. Great work.</td>', 'To me this conveys censorship of music, which is a form of silence. I could see it used in an add :) I appreciate the outside the box approach with your image and I think it get''s the point across nicely. This is my second time through the images, and I am bumping this up a couple because I am reading more into it. On the photography side, great work I understand the cord being cropped out at the bottim with your angle because it would have been a mess of cord, and due to the angle of the shot and the limited size of the entries here... you are left with a bit of black space at the top. Great work.', '2012-10-27 13:38:21.000000', NULL, 1),
(6892371, 1039069, 135629, '<td valign="top">Second time through the images, I don''t know how I missed the details he first time but I love this shot. It looks like a scene out of the game "LIMBO". Beautiful black and white. Bumping you up a few for this.</td>', 'Second time through the images, I don''t know how I missed the details he first time but I love this shot. It looks like a scene out of the game "LIMBO". Beautiful black and white. Bumping you up a few for this.', '2012-10-27 13:41:58.000000', NULL, 1),
(6892382, 1038508, 96751, '<td valign="top">Lovelyt ones, and nice angle, but a bit of blown out area</td>', 'Lovelyt ones, and nice angle, but a bit of blown out area', '2012-10-27 14:02:40.000000', NULL, 1),
(6892383, 1038990, 96751, '<td valign="top">I like the intention, but her stance and expression seem forced and unnatural</td>', 'I like the intention, but her stance and expression seem forced and unnatural', '2012-10-27 14:03:07.000000', NULL, 1),
(6892384, 1038843, 96751, '<td valign="top">Excellent image, and yes, physically it is silent, but the yell pose says sound to me</td>', 'Excellent image, and yes, physically it is silent, but the yell pose says sound to me', '2012-10-27 14:03:47.000000', NULL, 1),
(6892385, 1038138, 96751, '<td valign="top">Perfect stock image</td>', 'Perfect stock image', '2012-10-27 14:04:03.000000', NULL, 1),
(6892386, 1038617, 96751, '<td valign="top">Beautiful. Great balance and colors, although the green fringing around the tree trunks is quite pronounced. I think just a tiny bit of vignetting might have also helped focus our eye on the nun.</td>', 'Beautiful. Great balance and colors, although the green fringing around the tree trunks is quite pronounced. I think just a tiny bit of vignetting might have also helped focus our eye on the nun.', '2012-10-27 14:05:39.000000', NULL, 1),
(6892387, 1039044, 96751, '<td valign="top">Still attempting these images. Really tough. Nice Milky Way!</td>', 'Still attempting these images. Really tough. Nice Milky Way!', '2012-10-27 14:06:07.000000', NULL, 1),
(6892388, 1039046, 96751, '<td valign="top">I love how the trees look like faces, and the bare branches like hair blowing in the wind. How can you go wrong with fall colors and fog?</td>', 'I love how the trees look like faces, and the bare branches like hair blowing in the wind. How can you go wrong with fall colors and fog?', '2012-10-27 14:06:54.000000', NULL, 1),
(6892389, 1038942, 96751, '<td valign="top">Colorful abstract, with great sense of movement. Too abstract to convey silence to  me</td>', 'Colorful abstract, with great sense of movement. Too abstract to convey silence to  me', '2012-10-27 14:07:21.000000', NULL, 1),
(6892390, 1039059, 96751, '<td valign="top">Beautiful but seems quite oversharpened to me</td>', 'Beautiful but seems quite oversharpened to me', '2012-10-27 14:07:35.000000', NULL, 1),
(6892391, 1038853, 96751, '<td valign="top">Gorgeous.</td>', 'Gorgeous.', '2012-10-27 14:08:04.000000', NULL, 1),
(6892392, 1039017, 96751, '<td valign="top">I love that tree. I''m ambivalent about the pumpkins in the foreground. I think they distract from the much more interesting pumpkins, fence and tree in the bg.</td>', 'I love that tree. I''m ambivalent about the pumpkins in the foreground. I think they distract from the much more interesting pumpkins, fence and tree in the bg.', '2012-10-27 14:08:51.000000', NULL, 1),
(6892393, 1039047, 96751, '<td valign="top">Nice! Oh, and ick!</td>', 'Nice! Oh, and ick!', '2012-10-27 14:09:11.000000', NULL, 1),
(6892394, 1038838, 96751, '<td valign="top">Waaaay too much contrast for my taste</td>', 'Waaaay too much contrast for my taste', '2012-10-27 14:09:42.000000', NULL, 1),
(6892395, 1039063, 96751, '<td valign="top">A bold choice to have the main subject be blurred, B. And yet, somehow it works, emphasizing her alone-ness, and outsider-ness.</td>', 'A bold choice to have the main subject be blurred, B. And yet, somehow it works, emphasizing her alone-ness, and outsider-ness.', '2012-10-27 14:10:39.000000', NULL, 1),
(6892396, 1038868, 96751, '<td valign="top">Very expressive eyes</td>', 'Very expressive eyes', '2012-10-27 14:11:29.000000', NULL, 1),
(6892397, 1039040, 96751, '<td valign="top">The hat and sweater textures are really terrific.</td>', 'The hat and sweater textures are really terrific.', '2012-10-27 14:12:10.000000', NULL, 1),
