(6896344, 1039021, 96751, '<td valign="top">A gift from Texas. So wonderful to see you enter again!</td>', 'A gift from Texas. So wonderful to see you enter again!', '2012-11-02 12:01:09.000000', NULL, 0),
(6896350, 1039051, 96751, '<td valign="top">Geez, my comment is awful! Sorry about that, Penny!!!! Because this is really lovely. The light is just perfect</td>', 'Geez, my comment is awful! Sorry about that, Penny!!!! Because this is really lovely. The light is just perfect', '2012-11-02 12:03:26.000000', NULL, 0),
