(6896359, 1038508, 138630, '<td valign="top">I particularly liked the blocks of light and dark and the silhouette figures added nice interest.  I thought the geometric quality of the overall composition was very nice.</td>', 'I particularly liked the blocks of light and dark and the silhouette figures added nice interest.  I thought the geometric quality of the overall composition was very nice.', '2012-11-02 12:07:17.000000', NULL, 0),
(6896363, 1038988, 96751, '<td valign="top">Ha! Knew there were two similar entries, and now I understand :-)  Love that one is portrait and the other, landscape.</td>', 'Ha! Knew there were two similar entries, and now I understand :-)  Love that one is portrait and the other, landscape.', '2012-11-02 12:08:36.000000', NULL, 0),
(6896367, 1038962, 96751, '<td valign="top">Ha! Didn''t even notice the cars! This is so iconically NY I should have suspected it was you. Still don''t like that slash of light on the left...</td>', 'Ha! Didn''t even notice the cars! This is so iconically NY I should have suspected it was you. Still don''t like that slash of light on the left...', '2012-11-02 12:10:34.000000', NULL, 0),
