INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6896377, 1038980, 96530, '<td valign="top">Congratulations on a beautiful image Christophe. Reminds me a little bit of a landscape you did for the benefit of our Jawbones team ages ago. I''m sure you will remember the one I am referring to :)</td>', 'Congratulations on a beautiful image Christophe. Reminds me a little bit of a landscape you did for the benefit of our Jawbones team ages ago. I''m sure you will remember the one I am referring to :)', '2012-11-02 12:16:05.000000', NULL, 0),
(6896382, 1038605, 117534, '<td valign="top">LOL @ Tangurea.... I love it when we express our honest feelings during the challenge and are not influenced by who''s shot we think it maybe... I did not have the chance to look and vote on this soo I''m just now going thru who did what... And although I like it as is... I REALLY see Value in what Tanguera said!!  I might try something like this in the futuer and the soft thing will stick in my mind... There is great value in other views of our art... Thats what I LOVE so much about thi site!!!   NOw if someone would PLEASE teach me to edit again... sigh</td>', 'LOL @ Tangurea.... I love it when we express our honest feelings during the challenge and are not influenced by who''s shot we think it maybe... I did not have the chance to look and vote on this soo I''m just now going thru who did what... And although I like it as is... I REALLY see Value in what Tanguera said!!  I might try something like this in the futuer and the soft thing will stick in my mind... There is great value in other views of our art... Thats what I LOVE so much about thi site!!!   NOw if someone would PLEASE teach me to edit again... sigh', '2012-11-02 12:33:18.000000', NULL, 0),
(6896387, 1039021, 118154, '<td valign="top">This is a lovely image and really needed to be much higher,Congratulations on its making.</td>', 'This is a lovely image and really needed to be much higher,Congratulations on its making.', '2012-11-02 12:39:01.000000', NULL, 0),
(6896389, 1038937, 118154, '<td valign="top">Yes of course,you know you own my heart.</td>', 'Yes of course,you know you own my heart.', '2012-11-02 12:47:06.000000', NULL, 0),
(6896432, 1039021, 113156, '<td valign="top">Very lovely indeed, would have got a ten if I''d voted, stupid me.</td>', 'Very lovely indeed, would have got a ten if I''d voted, stupid me.', '2012-11-02 13:42:43.000000', NULL, 0),
(6896445, 1038980, 59029, '<td valign="top">Lovely shot, Christophe, and grats on the blue, but just curious as to why it seems so tiny?</td>', 'Lovely shot, Christophe, and grats on the blue, but just curious as to why it seems so tiny?', '2012-11-02 14:01:15.000000', NULL, 0),
(6896449, 1038980, 114969, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by snaffles:</b></div><hr/><i> Lovely shot, Christophe, and grats on the blue, but just curious as to why it seems so tiny? </i></td></tr></table> <br/> <br/>Thanks Susan! It is not particularly tiny, it is 800 pixels wide. I suppose this impression comes from the fact I used a 2:1 ratio, resulting in only 400 pixels vertically.</td>', 'Originally posted by snaffles: Lovely shot, Christophe, and grats on the blue, but just curious as to why it seems so tiny?   Thanks Susan! It is not particularly tiny, it is 800 pixels wide. I suppose this impression comes from the fact I used a 2:1 ratio, resulting in only 400 pixels vertically.', '2012-11-02 14:15:20.000000', NULL, 0),
(6896461, 1038870, 54446, '<td valign="top">I''m very surprised this didn''t finish much higher.  It was one of my favorites in this challenge.  Keep up the good work!</td>', 'I''m very surprised this didn''t finish much higher.  It was one of my favorites in this challenge.  Keep up the good work!', '2012-11-02 14:35:32.000000', NULL, 0),
(6896468, 1039051, 104230, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tanguera:</b></div><hr/><i> Geez, my comment is awful! Sorry about that, Penny!!!! Because this is really lovely. The light is just perfect </i></td></tr></table> <br/>Thanks for the updated comment! Now you know why Robert <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30861" rel="nofollow" target="_blank">bear_music</a> and I usually make a point of not entering similar pictures.  In this instance Robert suggested we do, in part to determine which image seemed more "silent" to DPC voters.<br/><br/><i>Message edited by author 2012-11-02 14:51:58.</i></td>', 'Originally posted by tanguera: Geez, my comment is awful! Sorry about that, Penny!!!! Because this is really lovely. The light is just perfect  Thanks for the updated comment! Now you know why Robert  bear_music and I usually make a point of not entering similar pictures.  In this instance Robert suggested we do, in part to determine which image seemed more "silent" to DPC voters.', '2012-11-02 14:45:13.000000', '2012-11-02 14:51:58.000000', 0),
(6896477, 1038634, 80096, '<td valign="top">Hey Chuck! You did worse then me and I only scored a 5.0!!</td>', 'Hey Chuck! You did worse then me and I only scored a 5.0!!', '2012-11-02 14:54:24.000000', NULL, 0),
